test_suite:
test('returns a function', () => {
  const { result } = renderHook(() => useCallbackRef(vi.fn()));
  expect(typeof result.current).toBe('function');
});

test('callback fires with element when called with element', () => {
  const cb = vi.fn();
  const { result } = renderHook(() => useCallbackRef(cb));
  const el = document.createElement('div');
  result.current(el);
  expect(cb).toHaveBeenCalledWith(el);
});

test('callback fires with null when called with null', () => {
  const cb = vi.fn();
  const { result } = renderHook(() => useCallbackRef(cb));
  result.current(null);
  expect(cb).toHaveBeenCalledWith(null);
});

test('always calls latest version of callback', () => {
  const cb1 = vi.fn();
  const cb2 = vi.fn();
  const { result, rerender } = renderHook(
    ({ cb }) => useCallbackRef(cb),
    { initialProps: { cb: cb1 } }
  );
  rerender({ cb: cb2 });
  const el = document.createElement('span');
  result.current(el);
  expect(cb2).toHaveBeenCalledWith(el);
  expect(cb1).not.toHaveBeenCalled();
});

// __hidden__
test('returned ref function is stable across renders', () => {
  const { result, rerender } = renderHook(({ cb }) => useCallbackRef(cb), {
    initialProps: { cb: vi.fn() }
  });
  const first = result.current;
  rerender({ cb: vi.fn() });
  expect(result.current).toBe(first);
});

solution:
import { useCallback, useRef } from 'react';

type RefCallback<T> = (element: T | null) => void;

export function useCallbackRef<T extends Element>(callback: (el: T | null) => void): RefCallback<T> {
  const callbackRef = useRef(callback);
  callbackRef.current = callback;
  return useCallback((el: T | null) => callbackRef.current(el), []);
}
